/// Interface de linha de comando do `kd`.
#[allow(
    clippy::struct_excessive_bools,
    reason = "flags de CLI; bools são o tipo natural"
)]
#[derive(Debug, Parser)]
#[command(
    name = "kd",
    version,
    about = "knudge — memória otimizada para LLM",
    after_help = help::AFTER_HELP
)]
pub struct Cli {
    /// Emite o resultado no envelope JSON (contrato de máquina).
    #[arg(long, global = true)]
    pub json: bool,
    /// Nível de log em stderr (`error|warn|info|debug|trace|off`).
    #[arg(
        long,
        global = true,
        value_name = "NÍVEL",
        default_value = "warn",
        value_parser = parse_log_level
    )]
    pub log_level: String,
    /// Silencia o stderr.
    #[arg(long, global = true)]
    pub quiet: bool,
    /// Subcomando; sem verbo o `kd` mostra o help (D171).
    #[command(subcommand)]
    pub command: Option<Command>,
}

/// Níveis válidos de log (conjunto fechado — D212).
const LOG_LEVELS: [&str; 6] = ["error", "warn", "info", "debug", "trace", "off"];

/// Valida `--log-level` contra o conjunto fechado (D212).
fn parse_log_level(raw: &str) -> Result<String, String> {
    if LOG_LEVELS.contains(&raw.to_ascii_lowercase().as_str()) {
        Ok(raw.to_string())
    } else {
        Err(format!(
            "nível de log inválido: {raw:?} ({})",
            suggest::hint(raw, &LOG_LEVELS)
        ))
    }
}

/// Verbos de topo.
#[derive(Debug, Subcommand)]
pub enum Command {
    /// Funda `.knudge/` no projeto e emite o prompt inicial.
    Init(InitArgs),
    /// Protocolo de uso estático (byte-idêntico por versão).
    Prime(PrimeArgs),
    /// Estado/handoff ponto-no-tempo.
    Rewind(RewindArgs),
    /// Toda pesquisa (recall, get e expand).
    Ask(AskArgs),
    /// Memória de agentes: consulta read-only de shards NDJSON (D220–D222).
    Ai(AiArgs),
    /// Toda escrita (create, update e arestas).
    Write(WriteArgs),
    /// Gestão de tarefas (`epic` ⊃ {`issue` ⊃ `task` | `task`}).
    Task {
        /// Subcomando de tarefa.
        #[command(subcommand)]
        command: TaskCommand,
    },
    /// Mapa de conhecimento (clusters estruturais e semânticos).
    Map(MapArgs),
    /// Manutenção (compact, learn, prune; só propõem, nunca agem).
    Maintenance {
        /// Subcomando de manutenção.
        #[command(subcommand)]
        command: MaintenanceCommand,
    },
    /// Saúde do corpus: 13 checks + auditoria, com reparo reversível (D163).
    Doctor(DoctorArgs),
    /// Fila de embeddings (`--status`/`--digest`) e worker (`service`; D170/D186).
    Drain(DrainArgs),
    /// Configuração do projeto.
    Config {
        /// Subcomando de configuração.
        #[command(subcommand)]
        command: ConfigCommand,
    },
    /// Soft-delete de notas.
    Forget(ForgetArgs),
    /// Commit de `notas/` + `eventos/`.
    Sync(SyncArgs),
    /// Instalação e utilitários do binário.
    #[command(name = "self")]
    SelfCmd {
        /// Subcomando de instalação.
        #[command(subcommand)]
        command: SelfCommand,
    },
}

impl Command {
    /// Nome canônico usado no envelope.
    #[must_use]
    pub fn name(&self) -> &'static str {
        match self {
            Self::Init(_) => "init",
            Self::Prime(_) => "prime",
            Self::Rewind(_) => "rewind",
            Self::Ask(_) => "ask",
            Self::Ai(_) => "ai",
            Self::Write(_) => "write",
            Self::Task { .. } => "task",
            Self::Map(_) => "map",
            Self::Maintenance { .. } => "maintenance",
            Self::Doctor(_) => "doctor",
            Self::Drain(_) => "drain",
            Self::Config { .. } => "config",
            Self::Forget(_) => "forget",
            Self::Sync(_) => "sync",
            Self::SelfCmd { .. } => "self",
        }
    }
}

