    fn periodo_rejects_inverted_dates() {
        let v = serde_json::json!({
            "periodo": { "dataInicial": "31-05-2026", "dataFinal": "01-05-2026" }
        });
        assert!(filtro_mtr_from_json(&v).is_err());
    }
